prts.feedbackvariables:
polytolist(p):=[coeff(p,x^3),coeff(p,x^2),coeff(p,x),ev(p,x=0)];
varsl:listofvars(expand(ans1));
ans1exp:expand(ans1);
for i:1 while i<=length(varsl) do (ans1exp:ev(ans1exp,varsl[i]=x));

varlist: listofvars(ans1exp);
goodvars: is(varlist=[x] or varlist=[]);
norepeats: is(length(unique(ans2))=length(ans2));

an:polytolist(ans1exp);
tat:polytolist(charpol);

gcf:0;
for i:1 while i<=length(tat) do (if an[i]=tat[i] then gcf:gcf+1);
mgcf:0;
for i:1 while i<=length(tat) do (if an[i]=-tat[i] then mgcf:mgcf+1);
ggcf:lmax([gcf,mgcf]);

gooddeg: is(hipow(ans1exp,x)=n);
metukan: is(coeff(ans1exp,x,n)=1 or coeff(ans1exp,x,n)=-1);
corpol: is(expand(ans1exp)=charpol or expand(-ans1exp)=charpol);

goodlength: is(length(ans2)<=n);

goodvals: containedIn(ans2,sols);
wrongvals: sublist(ans2,lambda([exp],not member(exp,sols)));
allvals: containedIn(sols,ans2);
